const G = (text, extra = {}) => ({ text, ...extra })
const fill = (template, vars) => Object.entries(vars).reduce((text, [key, value]) => text.replaceAll(`{${key}}`, value), template)
const keyOf = card => `${card.text}|${(card.options || []).join('|')}`.toLowerCase().replace(/\s+/g, ' ').trim()

function unique(cards, target = 1000) {
  const seen = new Set()
  const out = []
  for (const card of cards) {
    const key = keyOf(card)
    if (seen.has(key)) continue
    seen.add(key)
    out.push(card)
    if (out.length === target) return out
  }
  if (out.length < target) throw new Error(`Need ${target} unique cards, found ${out.length}`)
  return out
}

function combinations(items, size) {
  const out = []
  const walk = (start, picked) => {
    if (picked.length === size) {
      out.push([...picked])
      return
    }
    for (let i = start; i <= items.length - (size - picked.length); i += 1) {
      picked.push(items[i])
      walk(i + 1, picked)
      picked.pop()
    }
  }
  walk(0, [])
  return out
}

function stableHash(value) {
  let h = 2166136261
  for (let i = 0; i < value.length; i += 1) {
    h ^= value.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

function shuffled(values, salt) {
  return [...values].sort((a, b) => stableHash(`${salt}:${a.join?.('|') || a}`) - stableHash(`${salt}:${b.join?.('|') || b}`))
}

