function redCards(groups) {
  const cards = []
  groups.forEach((group, groupIndex) => {
    group.bases.forEach((base, baseIndex) => group.tails.forEach((tail, tailIndex) => {
      cards.push(G(`They ${base}, ${tail}.`, { sort: stableHash(`red:${groupIndex}:${baseIndex}:${tailIndex}`) }))
    }))
  })
  return cards.sort((a, b) => a.sort - b.sort).map(({ sort, ...card }) => card)
}

