function pettyCards(groups) {
  const out = []
  groups.forEach((group, groupIndex) => {
    group.triggers.forEach((trigger, triggerIndex) => group.reactions.forEach((reaction, reactionIndex) => {
      out.push(G(`Petty or valid: ${trigger}, so ${reaction}?`, { sort: stableHash(`petty:${groupIndex}:${triggerIndex}:${reactionIndex}`) }))
    }))
  })
  return out.sort((a, b) => a.sort - b.sort).map(({ sort, ...card }) => card)
}

