const storyLenses = ['that still makes you laugh','you would handle differently now','that taught you something unexpected','you rarely tell people about','where the ending surprised you']

function storyCards(groups) {
  const out = []
  groups.forEach((events, groupIndex) => events.forEach((event, eventIndex) => storyLenses.forEach((lens, lensIndex) => {
    out.push(G(`Tell me about ${event} ${lens}.`, { sort: stableHash(`story:${groupIndex}:${eventIndex}:${lensIndex}`) }))
  })))
  return out.sort((a, b) => a.sort - b.sort).map(({ sort, ...card }) => card)
}

function withStarters(categoryId, mode, generated) {
  return unique([...(starterPrompts[categoryId]?.[mode] || []), ...generated], 1000)
}

function makeMode(mode) {
  const themes = mode === 'friend' ? friendThemes : relationshipThemes
  const red = mode === 'friend' ? friendRedGroups : relationshipRedGroups
  const petty = mode === 'friend' ? friendPettyGroups : relationshipPettyGroups
  const stories = mode === 'friend' ? storyFriendEvents : storyRelationshipEvents

  return {
    'guess-my-answer': withStarters('guess-my-answer', mode, optionCards(themes, 'guess')),
    'rank-these': withStarters('rank-these', mode, optionCards(themes, 'rank')),
    'agree-disagree': withStarters('agree-disagree', mode, agreeCards(themes)),
    'one-has-to-go': withStarters('one-has-to-go', mode, optionCards(themes, 'one')),
    'keep-one-forever': withStarters('keep-one-forever', mode, optionCards(themes, 'keep')),
    'rate-it': withStarters('rate-it', mode, rateCards(themes, mode)),
    'this-or-that': withStarters('this-or-that', mode, optionCards(themes, 'this')),
    'red-green-depends': withStarters('red-green-depends', mode, redCards(red)),
    'petty-or-valid': withStarters('petty-or-valid', mode, pettyCards(petty)),
    'tell-the-story': withStarters('tell-the-story', mode, storyCards(stories)),
  }
}

const friend = makeMode('friend')
const relationship = makeMode('relationship')

export const newGamePrompts1000 = Object.fromEntries(
  Object.keys(friend).map(categoryId => [categoryId, { friend: friend[categoryId], relationship: relationship[categoryId] }]),
)

export const newGameIds1000 = new Set(Object.keys(newGamePrompts1000))
